    ## Complete this function
    # Function to find the sum of contiguous subarray with maximum sum.
    def maxSubArraySum(self, arr):
        n = len(arr)
        max_sum = float('-inf')

        # O(N^2) quadratic checks
        for i in range(n):
            curr_sum = 0
            for j in range(i, n):
                curr_sum += arr[j]
                if curr_sum > max_sum:
                    max_sum = curr_sum

        return max_sum

